"""Tests for Gemini Native response_schema Compatibility and Structured Memory."""

from nemawashi.agents.compliance import ComplianceArbiterAgent
from nemawashi.agents.finops import FinOpsArbiterAgent
from nemawashi.agents.reliability import SRESentinelAgent
from nemawashi.agents.security import SecurityGuardianAgent
from nemawashi.core.models import AgentProposal, StructuredAgentVote


def test_structured_agent_vote_json_schema():
    """Verify FIX HOLE 2: JSON Schema generated by StructuredAgentVote conforms to Gemini response_schema requirements."""
    schema = StructuredAgentVote.model_json_schema()

    assert "properties" in schema
    props = schema["properties"]

    assert "stakeholder_id" in props
    assert "vote" in props
    assert "risk_tags" in props
    assert "mitigation_requirements" in props

    # Check Enum constraints for Gemini
    stakeholder_enum = props["stakeholder_id"].get("enum")
    assert set(stakeholder_enum) == {"security", "compliance", "finops", "sre"}

    vote_enum = props["vote"].get("enum")
    assert set(vote_enum) == {"APPROVE", "REJECT", "MITIGATE"}


def test_stakeholder_agents_offline_fallback_schema_compliance():
    """Verify that all stakeholder agents produce 100% compliant StructuredAgentVote instances in offline mode."""
    proposal = AgentProposal(
        proposal_id="p-schema-test",
        proposing_agent="agent-worker",
        action_type="open_firewall_rule",
        action_description="Open firewall to 0.0.0.0/0 on port 443 with PII patient data",
        target_resource="patient-records-ingress",
        estimated_cost_usd=400.0,
        estimated_blast_radius=85,
    )

    sec_agent = SecurityGuardianAgent()
    sec_vote = sec_agent.evaluate(proposal)
    assert isinstance(sec_vote, StructuredAgentVote)
    assert sec_vote.stakeholder_id == "security"
    assert sec_vote.vote in ("APPROVE", "REJECT", "MITIGATE")

    comp_agent = ComplianceArbiterAgent()
    comp_vote = comp_agent.evaluate(proposal, prior_votes={"security": sec_vote})
    assert isinstance(comp_vote, StructuredAgentVote)
    assert comp_vote.stakeholder_id == "compliance"

    fin_agent = FinOpsArbiterAgent()
    fin_vote = fin_agent.evaluate(proposal, prior_votes={"security": sec_vote, "compliance": comp_vote})
    assert isinstance(fin_vote, StructuredAgentVote)
    assert fin_vote.stakeholder_id == "finops"

    sre_agent = SRESentinelAgent()
    sre_vote = sre_agent.evaluate(
        proposal,
        prior_votes={"security": sec_vote, "compliance": comp_vote, "finops": fin_vote},
    )
    assert isinstance(sre_vote, StructuredAgentVote)
    assert sre_vote.stakeholder_id == "sre"
